// Kotlin's inline is about ALLOCATION as much as call overhead.
inline fun <T> withLock(lock: Lock, block: () -> T): T {   // inline: block() is
    lock.lock()                                              // inlined at the call
    try { return block() } finally { lock.unlock() }         // site, no Function object
}                                                           // allocated per call

// use it in a hot loop: no lambda allocation per iteration
fun sum(lock: Lock, xs: IntArray): Int {
    var total = 0
    for (x in xs) withLock(lock) { total += x }   // inlined: block is code, not an object
    return total
}

inline fun retry(times: Int, block: () -> Unit) {
    for (i in 0 until times) { block(); if (i == times-1) return }  // non-local return works
}
